import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.D21_4UK8.js";const h=JSON.parse('{"title":"🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab & Studio Mic Mixer","description":"","frontmatter":{},"headers":[],"relativePath":"ja/audio-mics-guide.md","filePath":"ja/audio-mics-guide.md"}'),o={name:"ja/audio-mics-guide.md"};function l(r,t,i,d,c,p){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="🎙️-オーディオ・エンジニアリングマスターガイド-1x12-hardwood-cab-lab-studio-mic-mixer" tabindex="-1">🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab &amp; Studio Mic Mixer <a class="header-anchor" href="#🎙️-オーディオ・エンジニアリングマスターガイド-1x12-hardwood-cab-lab-studio-mic-mixer" aria-label="Permalink to &quot;🎙️ オーディオ・エンジニアリングマスターガイド：1x12 Hardwood Cab Lab &amp; Studio Mic Mixer&quot;">​</a></h1><h3 id="evm-12lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密" tabindex="-1">EVM-12Lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密 <a class="header-anchor" href="#evm-12lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密" aria-label="Permalink to &quot;EVM-12Lコーン音響物理、位相科学、デュアルマイキング、1トラックで完結するステレオ録音の秘密&quot;">​</a></h3><p><strong>TattooYou Vintage Amplifier &amp; Studio Suite | Main St Audio Labs</strong></p><hr><h1 id="第1部-音響物理と位相の基礎" tabindex="-1">第1部：音響物理と位相の基礎 <a class="header-anchor" href="#第1部-音響物理と位相の基礎" aria-label="Permalink to &quot;第1部：音響物理と位相の基礎&quot;">​</a></h1><hr><h2 id="🔊-1-evm-12lドライバーと無垢材-hardwood-キャビネット" tabindex="-1">🔊 1. EVM-12Lドライバーと無垢材（Hardwood）キャビネット <a class="header-anchor" href="#🔊-1-evm-12lドライバーと無垢材-hardwood-キャビネット" aria-label="Permalink to &quot;🔊 1. EVM-12Lドライバーと無垢材（Hardwood）キャビネット&quot;">​</a></h2><h3 id="a-スピーカー歪みゼロ-zero-speaker-breakup-と無限のヘッドルーム" tabindex="-1">A. スピーカー歪みゼロ（Zero Speaker Breakup）と無限のヘッドルーム <a class="header-anchor" href="#a-スピーカー歪みゼロ-zero-speaker-breakup-と無限のヘッドルーム" aria-label="Permalink to &quot;A. スピーカー歪みゼロ（Zero Speaker Breakup）と無限のヘッドルーム&quot;">​</a></h3><p>伝統的なギター用スピーカー（25W〜30Wのペーパーコーン）は、大出力時にコーン紙自体が歪み、高域に粗いサチュレーションを生み出し、低域のパンチを圧縮してしまいます。</p><p><strong>Electro-Voice EVM-12L</strong>（200W〜300W定格、7.5kgの大型セラミックマグネット、アルミダイキャストフレーム）は、それとは正反対の音響思想で作られています：</p><ul><li><strong>純粋な真空管ダイナミクス：</strong> スピーカーコーン自体が音を濁らせません。耳にする倍音とサチュレーションは、<strong>6L6真空管と&#39;78 Mark Iプリアンプ回路そのものの純粋なサウンド</strong>です。</li><li><strong>抜群の弦分離感：</strong> 複雑なコードワークやキース・リチャーズ特有のオープンGチューニングでも、すべての弦の音が混ざり合わずにクリアに響きます。</li></ul><h3 id="b-バスレフポート付き無垢材-hardwood-キャビネット" tabindex="-1">B. バスレフポート付き無垢材（Hardwood）キャビネット <a class="header-anchor" href="#b-バスレフポート付き無垢材-hardwood-キャビネット" aria-label="Permalink to &quot;B. バスレフポート付き無垢材（Hardwood）キャビネット&quot;">​</a></h3><p>一般的なオープンバックのコンボキャビネットとは異なり、チューニングされた前面バスレフポートを備えた無垢材キャビネットを採用：</p><ul><li><strong>タイトで正確な低域：</strong> <strong>80 Hz〜160 Hz</strong>のエネルギーをタイトに引き締め、ブーミーな低音の濁りを徹底的に排除します。</li></ul><hr><h2 id="🎯-2-マイキング・マトリックス" tabindex="-1">🎯 2. マイキング・マトリックス <a class="header-anchor" href="#🎯-2-マイキング・マトリックス" aria-label="Permalink to &quot;🎯 2. マイキング・マトリックス&quot;">​</a></h2><p>12インチのギタースピーカーは均一に音を放射しません。マイクをセンターから外周へ移動させることで、高域が自然にロールオフし、中低域の厚みが増します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>                  │                 スピーカーコーン               │</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │      ( -3 )      ( -2 )      ( -1 )   ( 0 )  │</span></span>
<span class="line"><span>                  │      外周        コーン面   キャップエッジ  センター│</span></span>
<span class="line"><span>                  │     (Dark)       (Warm)     (Sweet)   (Bright)│</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │  [ PORT ]  &lt;─── (バスレフポート)              │</span></span>
<span class="line"><span>                  └──────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">テイク</th><th style="text-align:left;">物理位置</th><th style="text-align:left;">周波数特性</th><th style="text-align:left;">サウンドキャラクターと最適な用途</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>0: Direct</code></strong></td><td style="text-align:left;"><strong>センター / Dust Cap</strong></td><td style="text-align:left;"><strong>4 kHz〜8 kHz</strong>を強力に強調。</td><td style="text-align:left;">鋭いピッキングアタックと輝くような高域。密集したミックスを切り裂くソロやファンクに最適。</td></tr><tr><td style="text-align:center;"><strong><code>+1: Edge</code></strong></td><td style="text-align:left;"><strong>キャップ外周エッジ</strong></td><td style="text-align:left;">抜けの良い高域と滑らかなロールオフ。</td><td style="text-align:left;">明瞭なバイト感を持つ王道クラシックロックのリズムトーン。</td></tr><tr><td style="text-align:center;"><strong><code>-1: Sweet</code></strong></td><td style="text-align:left;"><strong>キャップとコーンの境界</strong></td><td style="text-align:left;">音楽的で黄金のバランス（<strong>Sweet Spot</strong>）。</td><td style="text-align:left;"><strong>スタジオ基準の王道サウンド：</strong> タイトな低域、太い中域、シルキーな高域。あらゆる演奏の推奨初期設定。</td></tr><tr><td style="text-align:center;"><strong><code>-2: Warm</code></strong></td><td style="text-align:left;"><strong>コーン面</strong></td><td style="text-align:left;">丸みのある中域、5 kHz以上が滑らか。</td><td style="text-align:left;">オフアクシスの滑らかさ。テレキャスターやストラトのブリッジPUの耳障りな高域を抑えるのに最適。</td></tr><tr><td style="text-align:center;"><strong><code>-3: Dark</code></strong></td><td style="text-align:left;"><strong>外周エッジ</strong></td><td style="text-align:left;">深い低域、落ち着いた高域。</td><td style="text-align:left;">太くウォームなジャズやスモーキーなブルース、ダウンチューニングに最適。</td></tr><tr><td style="text-align:center;"><strong><code>Port: Bass</code></strong></td><td style="text-align:left;"><strong>前面バスレフポート</strong></td><td style="text-align:left;"><strong>80 Hz〜160 Hz</strong>の重低音ブースト。</td><td style="text-align:left;">前面の空気振動を収録。4x12スタックアンプのような胸に響く重低音パンチを追加。</td></tr><tr><td style="text-align:center;"><strong><code>Room 3D</code></strong></td><td style="text-align:left;"><strong>スタジオ空間ペア</strong></td><td style="text-align:left;">3Dの自然な初期反射音と空気感。</td><td style="text-align:left;">空間に設置されたステレオコンデンサーペア。「箱鳴り感のない平坦な音」を解消し、本物の部屋の響きを付加。</td></tr></tbody></table><hr><h2 id="🎧-3-left-l-テイクとright-r-テイクの物理的差異" tabindex="-1">🎧 3. Left（L）テイクとRight（R）テイクの物理的差異 <a class="header-anchor" href="#🎧-3-left-l-テイクとright-r-テイクの物理的差異" aria-label="Permalink to &quot;🎧 3. Left（L）テイクとRight（R）テイクの物理的差異&quot;">​</a></h2><p>すべてのマイク位置に <strong><code>L</code>（左）</strong> と <strong><code>R</code>（右）</strong> のテイクが収録されています：</p><h3 id="なぜ円形のスピーカーで左右の音が異なるのか" tabindex="-1">なぜ円形のスピーカーで左右の音が異なるのか？ <a class="header-anchor" href="#なぜ円形のスピーカーで左右の音が異なるのか" aria-label="Permalink to &quot;なぜ円形のスピーカーで左右の音が異なるのか？&quot;">​</a></h3><ol><li><strong>ボイスコイル・ティンセルリード線の質量：</strong> 端子とコイルを繋ぐ編組線（ティンセルリード）はコーンの片側にハンダ付けされています。この微細な質量差が左右の振動特性に有機的な違いを生み出します。</li><li><strong>木目と空気の流れ：</strong> 無垢材の木目密度とポート内の気流により、高品位スタジオマイクだけが捉えられる微細な音響の非対称性が生まれます。</li></ol><hr><h2 id="🔬-4-位相科学-コムフィルター-音の打ち消し合い-の完全排除" tabindex="-1">🔬 4. 位相科学：コムフィルター（音の打ち消し合い）の完全排除 <a class="header-anchor" href="#🔬-4-位相科学-コムフィルター-音の打ち消し合い-の完全排除" aria-label="Permalink to &quot;🔬 4. 位相科学：コムフィルター（音の打ち消し合い）の完全排除&quot;">​</a></h2><h3 id="a-実機スタジオでの位相の罠" tabindex="-1">A. 実機スタジオでの位相の罠 <a class="header-anchor" href="#a-実機スタジオでの位相の罠" aria-label="Permalink to &quot;A. 実機スタジオでの位相の罠&quot;">​</a></h3><p>実機のアンプの前に2本のマイクを立てる際、距離がわずか1〜2ミリずれるだけで音の到達時間にズレが生じます：</p><ul><li>その時間差に一致する周波数が逆位相（180度）となり、<strong>互いに打ち消し合ってしまいます</strong>。</li><li><strong>その結果：</strong> 低域が完全に消え、薄っぺらく鼻づまりのような「缶詰の音」になります。</li></ul><h3 id="b-tattooyouのサンプル精度位相整合" tabindex="-1">B. TattooYouのサンプル精度位相整合 <a class="header-anchor" href="#b-tattooyouのサンプル精度位相整合" aria-label="Permalink to &quot;B. TattooYouのサンプル精度位相整合&quot;">​</a></h3><p>TattooYouでは、すべてのIRテイクに**最小位相変換（Minimum Phase Transform）**を適用しています：</p><ol><li>すべてのマイク収録波形が<strong>サンプル0（$t = 0$）で正確にスタート</strong>します。</li><li><strong>正の位相相関（$&gt; +0.92$）：</strong> 80 Hz〜3 kHzの基音帯域はほぼ$+1.0$で同位相です。<strong>低域が打ち消されることなく、パンチとなって加算されます</strong>。</li><li><strong>高域の自然な質感（&gt; 4 kHz）：</strong> 超高域の微細な位相差がアナログ的なスムージングとして機能し、耳障りなピークを自然に整えます。</li></ol><hr><h1 id="第2部-tattooyouプラグインでの実践活用法" tabindex="-1">第2部：TattooYouプラグインでの実践活用法 <a class="header-anchor" href="#第2部-tattooyouプラグインでの実践活用法" aria-label="Permalink to &quot;第2部：TattooYouプラグインでの実践活用法&quot;">​</a></h1><hr><h2 id="🎛️-5-dspアーキテクチャ-並列デュアル・コンボリューション" tabindex="-1">🎛️ 5. DSPアーキテクチャ：並列デュアル・コンボリューション <a class="header-anchor" href="#🎛️-5-dspアーキテクチャ-並列デュアル・コンボリューション" aria-label="Permalink to &quot;🎛️ 5. DSPアーキテクチャ：並列デュアル・コンボリューション&quot;">​</a></h2><p>TattooYouは単一の静的IRに縛られることなく、2系統のゼロレイテンシー・コンボリューションエンジン（<code>cab1Convolution</code> / <code>cab2Convolution</code>）を等電力カーブで駆動します：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                                  プリアンプ＆6L6パワーアンプ信号</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                       ┌────────────────────────┴────────────────────────┐</span></span>
<span class="line"><span>                       ▼                                                 ▼</span></span>
<span class="line"><span>             [ コンボリューション MIC 1 ]                      [ コンボリューション MIC 2 ]</span></span>
<span class="line"><span>             テイク：57 L (-1) Sweet                            テイク：87 L (0) Direct (または 57 R)</span></span>
<span class="line"><span>             フェーダー：-24 dB〜+6 dB                          フェーダー：-24 dB〜+6 dB</span></span>
<span class="line"><span>             音量比率：w1                                       位相：通常 / 反転（Ø）</span></span>
<span class="line"><span>                       │                                       音量比率：w2</span></span>
<span class="line"><span>                       │                                                 │</span></span>
<span class="line"><span>                       └────────────────────────┬────────────────────────┘</span></span>
<span class="line"><span>                                                ▼</span></span>
<span class="line"><span>                                    CAB LAB マスターセクション</span></span>
<span class="line"><span>                                 （等電力 CAB BLEND コントロール）</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                        ┌───────────────────────┴───────────────────────┐</span></span>
<span class="line"><span>                        ▼                                               ▼</span></span>
<span class="line"><span>               MONO SUM モード                                STEREO SPREAD 3D モード</span></span>
<span class="line"><span>          センター加算合成：                                     左チャンネル ＝ Mic 1 * (w1 * √2)</span></span>
<span class="line"><span>          Out ＝ (Mic1 * w1) ＋ (Mic2 * w2)                      右チャンネル ＝ Mic 2 * (w2 * √2)</span></span></code></pre></div><hr><h2 id="⚖️-6-mono-sum-vs-stereo-spread-用途に応じた使い分け" tabindex="-1">⚖️ 6. MONO SUM vs STEREO SPREAD：用途に応じた使い分け <a class="header-anchor" href="#⚖️-6-mono-sum-vs-stereo-spread-用途に応じた使い分け" aria-label="Permalink to &quot;⚖️ 6. MONO SUM vs STEREO SPREAD：用途に応じた使い分け&quot;">​</a></h2><hr><h3 id="a-mono-sum-ステレオ・スプレッド-off" tabindex="-1">A. MONO SUM（ステレオ・スプレッド OFF） <a class="header-anchor" href="#a-mono-sum-ステレオ・スプレッド-off" aria-label="Permalink to &quot;A. MONO SUM（ステレオ・スプレッド OFF）&quot;">​</a></h3><p>両方のマイクが信号を処理し、トラックのセンターに加算されます。</p><ul><li><strong>同一マイクのL＋R加算による高域スムージング（コーン・アベレージング）：</strong><ul><li>Mic 1: <code>57 L (-1) Sweet</code> ＋ Mic 2: <code>57 R (-1) Sweet</code>（<strong>Blend 50%</strong>）</li><li><strong>効果：</strong> 左右の微細な共振ピークが互いを補い合い、イコライザーを使わずに耳障りな高域のトゲを丸め、太く有機的な中域を作り出します。</li></ul></li><li><strong>ダイナミック＋コンデンサーの黄金ブレンド：</strong><ul><li><strong>70% Mic 1（57 Sweet）＋ 30% Mic 2（87 Direct）：</strong> 57の噛みつくアタックと、87の深い低域と空気感が融合。</li></ul></li><li><strong>重低音の注入（57 Sweet ＋ BassPort）：</strong><ul><li>ピッキングの輪郭を保ちながら、4x12キャビネット級の低音の重みをプラス。</li></ul></li></ul><hr><h3 id="b-stereo-spread-3d-ステレオ・スプレッド-on" tabindex="-1">B. STEREO SPREAD 3D（ステレオ・スプレッド ON） <a class="header-anchor" href="#b-stereo-spread-3d-ステレオ・スプレッド-on" aria-label="Permalink to &quot;B. STEREO SPREAD 3D（ステレオ・スプレッド ON）&quot;">​</a></h3><p>Mic 1が左チャンネル、Mic 2が右チャンネルに**+3 dB（$\\sqrt{2}$）の自動音量補正**を伴って出力されます。</p><h4 id="🚀-1トラックで完結するステレオ録音の秘密-トラック複製の省略" tabindex="-1">🚀 1トラックで完結するステレオ録音の秘密（トラック複製の省略） <a class="header-anchor" href="#🚀-1トラックで完結するステレオ録音の秘密-トラック複製の省略" aria-label="Permalink to &quot;🚀 1トラックで完結するステレオ録音の秘密（トラック複製の省略）&quot;">​</a></h4><ul><li><strong>DAWのトラックを複製する必要がありません：</strong> 2本のトラックを録音したり、タイミングをずらしたり、疑似ステレオプラグインを挟む手間がゼロになります。</li><li><strong>本物のアナログ3D空間：</strong> 同じキャビネットの左右の音響差を両耳に届けることで、脳が「目の前に本物のアンプがある空間」を立体的に認識します。</li></ul><h4 id="ステレオモードでのブレンド活用法" tabindex="-1">ステレオモードでのブレンド活用法： <a class="header-anchor" href="#ステレオモードでのブレンド活用法" aria-label="Permalink to &quot;ステレオモードでのブレンド活用法：&quot;">​</a></h4><ol><li><strong>ウルトラワイド・ダブルトラッキング：</strong><ul><li>Mic 1: <code>57 L (-1) Sweet</code>（左耳） ＋ Mic 2: <code>57 R (-1) Sweet</code>（右耳）、<strong>Blend 50%</strong>。1トラックだけで圧倒的なステレオギターの壁が完成。</li></ul></li><li><strong>スタジオ・ライブルーム3D：</strong><ul><li>Mic 1: <code>57 L (-1) Sweet</code>（前面ダイレクト） ＋ Mic 2: <code>87 Room L 3D</code>（空間のアンビエンス）、<strong>Blend 25%〜30%</strong>。</li></ul></li><li><strong>ヘッドホン演奏時の疲労軽減：</strong><ul><li>頭の中心で鳴るモノラル特有の聴覚疲労を解消し、長時間の演奏やミックスでも耳が疲れません。</li></ul></li></ol><hr><h2 id="🏆-7-スタジオ・リファレンス・プリセット" tabindex="-1">🏆 7. スタジオ・リファレンス・プリセット <a class="header-anchor" href="#🏆-7-スタジオ・リファレンス・プリセット" aria-label="Permalink to &quot;🏆 7. スタジオ・リファレンス・プリセット&quot;">​</a></h2><ol><li>🎸 <strong>Studio Standard:</strong> <code>57 L Sweet</code> ＋ <code>87 L Direct</code>（Blend 30%, Mono）— 王道のモダンロックサウンド。</li><li>🥊 <strong>Heavy Punch:</strong> <code>57 L Sweet</code> ＋ <code>57 L BassPort</code>（Blend 25%, Mono）— 4x12級の重低音リフ。</li><li>🌌 <strong>Live Room 3D:</strong> <code>57 L Sweet</code> ＋ <code>87 Room L 3D</code>（Blend 25%, Stereo）— リアルなスタジオ空間。</li><li>🎧 <strong>Wide Double Track:</strong> <code>57 L Sweet</code> ＋ <code>57 R Sweet</code>（Blend 50%, Stereo）— 1トラック完結のウルトラワイドステレオ。</li><li>⚡ <strong>Solo 57 Classic:</strong> <code>57 L Sweet</code>（Mono）— ダイレクトでパンチのある王道トーン。</li><li>✨ <strong>Solo 87 Hi-Fi:</strong> <code>87 L Direct</code>（Mono）— 最高峰のハイファイ・スタジオクオリティ。</li></ol><hr><h2 id="💡-8-dawワークフロー" tabindex="-1">💡 8. DAWワークフロー <a class="header-anchor" href="#💡-8-dawワークフロー" aria-label="Permalink to &quot;💡 8. DAWワークフロー&quot;">​</a></h2><ol><li><strong>フロントパネルでの即時調整：</strong> アンプ前面右上の <strong><code>BLEND</code></strong> ミニノブで、オーバーレイを開くことなく演奏中にブレンド比率を調整可能。</li><li><strong>モノラル互換性の完全保証：</strong> サンプル精度のアライメントにより、スマートフォンやモノラルスピーカーで再生しても<strong>音の打ち消し合い（フェイズアウト）が一切発生しません</strong>。</li></ol>`,57)])])}const u=a(o,[["render",l]]);export{h as __pageData,u as default};
